//! Pure-`std` Rust port of the `inflection-cpp` library.
//!
//! The public surface mirrors the C++ `inflection::Inflector` class: a set of
//! associated functions that take a word and return the inflected form.
//!
//! See [`inflection::Inflector`] for the API and `src/inflection/rules.rs` for
//! the rule tables that drive [`Inflector::pluralize`] and
//! [`Inflector::singularize`].

pub mod inflection;

pub use crate::inflection::Inflector;

