//! Byte level case handling.
//!
//! The C++ original calls `std::toupper` / `std::tolower` / `std::isupper` on
//! individual `char`s while the process is still in the default `"C"` locale,
//! so only the 52 ASCII letters are ever remapped. Every other byte — punctuation,
//! digits and in particular the lead/continuation bytes of a UTF-8 sequence — is
//! returned unchanged. Working a byte at a time reproduces that exactly: an input
//! of `ünïcode` upcases to `üNïCODE`, not `ÜNÏCODE`.

/// ASCII-only `std::toupper`.
pub fn to_upper(b: u8) -> u8 {
    if b.is_ascii_lowercase() {
        b - 32
    } else {
        b
    }
}

/// ASCII-only `std::tolower`.
pub fn to_lower(b: u8) -> u8 {
    if b.is_ascii_uppercase() {
        b + 32
    } else {
        b
    }
}

/// ASCII-only `std::isupper`.
pub fn is_upper(b: u8) -> bool {
    b.is_ascii_uppercase()
}

/// Uppercases every byte of `word`.
pub fn upcase(word: &[u8]) -> Vec<u8> {
    word.iter().copied().map(to_upper).collect()
}

/// Lowercases every byte of `word`.
pub fn downcase(word: &[u8]) -> Vec<u8> {
    word.iter().copied().map(to_lower).collect()
}

/// Uppercases the first byte, leaving the remainder of `word` alone.
///
/// An empty word is returned untouched, mirroring the `!word.empty()` guard
/// around the C++ `word[0] = std::toupper(word[0])`.
pub fn capitalize_first(mut word: Vec<u8>) -> Vec<u8> {
    if let Some(first) = word.first_mut() {
        *first = to_upper(*first);
    }
    word
}

/// Replaces every occurrence of the byte `from` with `to`.
pub fn replace_byte(word: &[u8], from: u8, to: u8) -> Vec<u8> {
    word.iter()
        .map(|&b| if b == from { to } else { b })
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn ascii_letters_only() {
        assert_eq!(upcase(b"aBc_1-z"), b"ABC_1-Z".to_vec());
        assert_eq!(downcase(b"aBc_1-Z"), b"abc_1-z".to_vec());
    }

    #[test]
    fn utf8_bytes_pass_through() {
        // "ünïcode" -> "üNïCODE": the 0xC3/0xBC/0xAF bytes are untouched.
        assert_eq!(
            upcase("ünïcode".as_bytes()),
            "üNïCODE".as_bytes().to_vec()
        );
    }

    #[test]
    fn capitalize_first_is_empty_safe() {
        assert_eq!(capitalize_first(Vec::new()), Vec::<u8>::new());
        assert_eq!(capitalize_first(b"_x".to_vec()), b"_x".to_vec());
        assert_eq!(capitalize_first(b"cat".to_vec()), b"Cat".to_vec());
    }
}

