//! literal inside brackets, exactly as `std::regex` treats it.

/// One step of a flattened alternative.
#[derive(Debug, Clone, PartialEq, Eq)]
enum Item {
    /// `^` — succeeds only at offset 0.
    Start,
    /// `$` — succeeds only at end of input.
    End,
    /// A literal byte.
    Byte(u8),
    /// A `[…]` / `[^…]` character class.
    Class { negated: bool, set: Vec<u8> },
    /// Marks where capture group `n` opens.
    Open(usize),
    /// Marks where capture group `n` closes.
    Close(usize),
}

/// Parse tree node.
#[derive(Debug, Clone)]
enum Node {
    Item(Item),
    /// `( … )` or `(?: … )`; `index` is `None` for a non-capturing group.
    Group { index: Option<usize>, branches: Vec<Vec<Node>> },
}

/// A pattern compiled into an ordered list of fixed-length alternatives.
#[derive(Debug, Clone)]
pub struct Regex {
    alternatives: Vec<Vec<Item>>,
    group_count: usize,
}

/// Where a successful match landed, plus its capture group spans.
#[derive(Debug, Clone)]
pub struct Match {
    pub start: usize,
    pub end: usize,
    /// `captures[n]` is the span of group `n + 1`, or `None` if that group was
    /// not part of the branch that matched.
    captures: Vec<Option<(usize, usize)>>,
}

impl Regex {
    /// Compiles `pattern`.
    ///
    /// # Panics
    ///
    /// Panics on malformed input or on syntax outside the supported subset. Every
    /// pattern in this crate is a compile-time constant from the rule tables, so
    /// a panic here means a typo in those tables and not bad user input.
    pub fn new(pattern: &str) -> Regex {
        let bytes = pattern.as_bytes();
        let mut parser = Parser { bytes, pos: 0, groups: 0 };
        let branches = parser.parse_alternation();
        assert!(
            parser.pos == bytes.len(),
            "unbalanced ')' in regex {pattern:?}"
        );
        let group_count = parser.groups;

        let mut alternatives = Vec::new();
        for branch in &branches {
            alternatives.extend(expand_sequence(branch));
        }
        Regex { alternatives, group_count }
    }

    /// First match at or after `from`, mirroring `std::regex_search`.
    pub fn find_at(&self, text: &[u8], from: usize) -> Option<Match> {
        for start in from..=text.len() {
            for alternative in &self.alternatives {
                let mut captures = vec![None; self.group_count];
                if let Some(end) = try_alternative(alternative, text, start, &mut captures) {
                    return Some(Match { start, end, captures });
                }
            }
        }
        None
    }

    /// True when the pattern matches anywhere in `text` (`std::regex_search`).
    pub fn is_match(&self, text: &[u8]) -> bool {
        self.find_at(text, 0).is_some()
    }

    /// Replaces every match with `replacement`, mirroring `std::regex_replace`.
    ///
    /// `replacement` may contain `$1` … `$9` group references and `$&` for the
    /// whole match; a `$` followed by anything else is a literal `$`.
    pub fn replace_all(&self, text: &[u8], replacement: &str) -> Vec<u8> {
        let mut out = Vec::with_capacity(text.len() + replacement.len());
        let mut cursor = 0usize;

        while cursor <= text.len() {
            let Some(m) = self.find_at(text, cursor) else { break };
            out.extend_from_slice(&text[cursor..m.start]);
            self.expand_replacement(replacement, text, &m, &mut out);

            if m.end == m.start {
                // A zero-width match (e.g. the plural rule `$`) must not spin in
                // place: copy one byte across and step past it.
                if m.start < text.len() {
                    out.push(text[m.start]);
                }
                cursor = m.start + 1;
            } else {
                cursor = m.end;
            }
        }

        if cursor < text.len() {
            out.extend_from_slice(&text[cursor..]);
        }
        out
    }

    fn expand_replacement(&self, replacement: &str, text: &[u8], m: &Match, out: &mut Vec<u8>) {
        let repl = replacement.as_bytes();
        let mut i = 0usize;
        while i < repl.len() {
            if repl[i] != b'$' || i + 1 >= repl.len() {
                out.push(repl[i]);
                i += 1;
                continue;
            }
            match repl[i + 1] {
                b'&' => {
                    out.extend_from_slice(&text[m.start..m.end]);
                    i += 2;
                }
                b'$' => {
                    out.push(b'$');
                    i += 2;
                }
                b'0'..=b'9' => {
                    // ECMAScript prefers the two-digit reading when that group
                    // exists, otherwise falls back to a single digit.
                    let mut digits = 1;
                    let mut group = (repl[i + 1] - b'0') as usize;
                    if i + 2 < repl.len() && repl[i + 2].is_ascii_digit() {
                        let two = group * 10 + (repl[i + 2] - b'0') as usize;
                        if two >= 1 && two <= self.group_count {
                            group = two;
                            digits = 2;
                        }
                    }
                    if group >= 1 && group <= self.group_count {
                        if let Some((s, e)) = m.captures[group - 1] {
                            out.extend_from_slice(&text[s..e]);
                        }
                        i += 1 + digits;
                    } else {
                        out.push(repl[i]);
                        i += 1;
                    }
                }
                _ => {
                    out.push(repl[i]);
                    i += 1;
                }
            }
        }
    }
}

/// Walks one flattened alternative, returning the end offset on success.
fn try_alternative(
    items: &[Item],
    text: &[u8],
    start: usize,
    captures: &mut [Option<(usize, usize)>],
) -> Option<usize> {
    let mut pos = start;
    for item in items {
        match item {
            Item::Start => {
                if pos != 0 {
                    return None;
                }
            }
            Item::End => {
                if pos != text.len() {
                    return None;
                }
            }
            Item::Byte(expected) => {
                if pos < text.len() && text[pos] == *expected {
                    pos += 1;
                } else {
                    return None;
                }
            }
            Item::Class { negated, set } => {
                if pos < text.len() && (set.contains(&text[pos]) != *negated) {
                    pos += 1;
                } else {
                    return None;
                }
            }
            Item::Open(n) => captures[n - 1] = Some((pos, pos)),
            Item::Close(n) => {
                if let Some((s, _)) = captures[n - 1] {
                    captures[n - 1] = Some((s, pos));
                }
            }
        }
    }
    Some(pos)
}

/// Cartesian product of a sequence's per-node expansions.
///
/// The leftmost node varies slowest, which is the order ECMAScript backtracking
/// would visit the branches in.
fn expand_sequence(nodes: &[Node]) -> Vec<Vec<Item>> {
    let mut result: Vec<Vec<Item>> = vec![Vec::new()];
    for node in nodes {
        let expansions = expand_node(node);
        let mut next = Vec::with_capacity(result.len() * expansions.len());
        for prefix in &result {
            for expansion in &expansions {
                let mut combined = prefix.clone();
                combined.extend_from_slice(expansion);
                next.push(combined);
            }
        }
        result = next;
    }
    result
}

fn expand_node(node: &Node) -> Vec<Vec<Item>> {
    match node {
        Node::Item(item) => vec![vec![item.clone()]],
        Node::Group { index, branches } => {
            let mut out = Vec::new();
            for branch in branches {
                for mut expansion in expand_sequence(branch) {
                    if let Some(n) = index {
                        let mut wrapped = Vec::with_capacity(expansion.len() + 2);
                        wrapped.push(Item::Open(*n));
                        wrapped.append(&mut expansion);
                        wrapped.push(Item::Close(*n));
                        out.push(wrapped);
                    } else {
                        out.push(expansion);
                    }
                }
            }
            out
        }
    }
}

struct Parser<'a> {
    bytes: &'a [u8],
    pos: usize,
    groups: usize,
}

impl<'a> Parser<'a> {
    /// `alternation := sequence ('|' sequence)*`
    fn parse_alternation(&mut self) -> Vec<Vec<Node>> {
        let mut branches = vec![self.parse_sequence()];
        while self.pos < self.bytes.len() && self.bytes[self.pos] == b'|' {
            self.pos += 1;
            branches.push(self.parse_sequence());
        }
        branches
    }

    /// `sequence := item*`, stopping at `|` or `)`.
    fn parse_sequence(&mut self) -> Vec<Node> {
        let mut nodes = Vec::new();
        while self.pos < self.bytes.len() {
            match self.bytes[self.pos] {
                b'|' | b')' => break,
                b'(' => {
                    self.pos += 1;
                    let index = if self.bytes[self.pos..].starts_with(b"?:") {
                        self.pos += 2;
                        None
                    } else {
                        self.groups += 1;
                        Some(self.groups)
                    };
                    let branches = self.parse_alternation();
                    assert_eq!(
                        self.bytes.get(self.pos),
                        Some(&b')'),
                        "unterminated group in regex"
                    );
                    self.pos += 1;
                    nodes.push(Node::Group { index, branches });
                }
                b'[' => {
                    self.pos += 1;
                    let negated = self.bytes.get(self.pos) == Some(&b'^');
                    if negated {
                        self.pos += 1;
                    }
                    let mut set = Vec::new();
                    while self.pos < self.bytes.len() && self.bytes[self.pos] != b']' {
                        // `|` and other metacharacters are literals in here; no
                        // rule uses a `a-z` range or a `\` escape.
                        set.push(self.bytes[self.pos]);
                        self.pos += 1;
                    }
                    assert_eq!(
                        self.bytes.get(self.pos),
                        Some(&b']'),
                        "unterminated character class in regex"
                    );
                    self.pos += 1;
                    nodes.push(Node::Item(Item::Class { negated, set }));
                }
                b'^' => {
                    self.pos += 1;
                    nodes.push(Node::Item(Item::Start));
                }
                b'$' => {
                    self.pos += 1;
                    nodes.push(Node::Item(Item::End));
                }
                b'\\' => {
                    self.pos += 1;
                    let escaped = *self
                        .bytes
                        .get(self.pos)
                        .expect("trailing backslash in regex");
                    self.pos += 1;
                    nodes.push(Node::Item(Item::Byte(escaped)));
                }
                other => {
                    assert!(
                        !matches!(other, b'*' | b'+' | b'?' | b'{' | b'.'),
                        "regex syntax {:?} is outside the supported subset",
                        other as char
                    );
                    self.pos += 1;
                    nodes.push(Node::Item(Item::Byte(other)));
                }
            }
        }
        nodes
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn anchors_and_literals() {
        let re = Regex::new("s$");
        assert_eq!(re.replace_all(b"class", ""), b"clas".to_vec());
        assert_eq!(re.replace_all(b"cat", ""), b"cat".to_vec());
        assert!(!re.is_match(b"cat"));
    }

    #[test]
    fn zero_width_match_appends() {
        let re = Regex::new("$");
        assert_eq!(re.replace_all(b"box", "s"), b"boxs".to_vec());
        // `$` is not multiline: it only matches at the very end.
        assert_eq!(re.replace_all(b"ab\ncd", "s"), b"ab\ncds".to_vec());
    }

    #[test]
    fn alternation_is_leftmost_first() {
        let re = Regex::new("(x|ch|ss|sh)es$");
        assert_eq!(re.replace_all(b"boxes", "$1"), b"box".to_vec());
        assert!(!re.is_match(b"buses"));
    }

    #[test]
    fn unmatched_group_expands_to_empty() {
        let re = Regex::new("((a)naly|(b)a|(t)he)ses$");
        assert_eq!(re.replace_all(b"analyses", "$1$2sis"), b"analyasis".to_vec());
        assert_eq!(re.replace_all(b"bases", "$1$2sis"), b"basis".to_vec());
        // Leftmost match: the `(b)a` branch starts at offset 4 of "databases".
        assert_eq!(
            re.replace_all(b"databases", "$1$2sis"),
            b"databasis".to_vec()
        );
    }

    #[test]
    fn pipe_inside_class_is_literal() {
        let re = Regex::new("([m|l])ice$");
        assert_eq!(re.replace_all(b"mice", "$1ouse"), b"mouse".to_vec());
        assert_eq!(re.replace_all(b"|ice", "$1ouse"), b"|ouse".to_vec());
        assert!(!re.is_match(b"dice"));
    }

    #[test]
    fn negated_class() {
        let re = Regex::new("([^f])ves$");
        assert_eq!(re.replace_all(b"wolves", "$1fe"), b"wolfe".to_vec());
        assert!(!re.is_match(b"fves"));
    }

    #[test]
    fn non_capturing_group_and_group_numbering() {
        let re = Regex::new("(?:([^f])fe|([lr])f)$");
        assert_eq!(re.replace_all(b"knife", "$1$2ves"), b"knives".to_vec());
        assert_eq!(re.replace_all(b"half", "$1$2ves"), b"halves".to_vec());
    }

    #[test]
    fn top_level_alternation() {
        let re = Regex::new("(matr|vert|ind)ix|ex$");
        assert_eq!(re.replace_all(b"matrix", "$1ices"), b"matrices".to_vec());
        assert_eq!(re.replace_all(b"vertex", "$1ices"), b"vertices".to_vec());
    }

    #[test]
    fn caret_inside_group() {
        let re = Regex::new("(^analy)ses$");
        assert_eq!(re.replace_all(b"analyses", "$1sis"), b"analysis".to_vec());
        assert!(!re.is_match(b"reanalyses"));
    }

    #[test]
    fn matches_are_case_sensitive() {
        assert!(!Regex::new("s$").is_match(b"BOXES"));
        assert!(!Regex::new("^(ox)en$").is_match(b"OXEN"));
    }
}

