//! replaces with `$1$2sis` rather than Rails' `\1sis`, so `analyses` — the one
//! branch with a second capture group — singularises to `analyasis` while
//! `bases`, `theses` and friends come out correctly. And none of the patterns
//! carry `std::regex::icase`, so the rules are case-sensitive: `Boxes` becomes
//! `Box` but `BOXES` is left exactly as it is.

use std::sync::OnceLock;

use super::regex::Regex;

/// A pattern paired with its replacement template.
pub struct Rule {
    pub pattern: &'static str,
    pub replacement: &'static str,
    regex: Regex,
}

impl Rule {
    /// True when this rule applies to `word`.
    pub fn matches(&self, word: &[u8]) -> bool {
        self.regex.is_match(word)
    }

    /// Applies this rule to `word`.
    pub fn apply(&self, word: &[u8]) -> Vec<u8> {
        self.regex.replace_all(word, self.replacement)
    }
}

/// Rules used to turn a singular word into a plural one.
const PLURAL_RULES: &[(&str, &str)] = &[
    ("$", "s"),
    ("s$", "s"),
    ("(ax|test)is$", "$1es"),
    ("(octop|vir)us$", "$1i"),
    ("(alias|status)$", "$1es"),
    ("(bu)s$", "$1ses"),
    ("(buffal|tomat)o$", "$1oes"),
    ("([ti])um$", "$1a"),
    ("sis$", "ses"),
    ("(?:([^f])fe|([lr])f)$", "$1$2ves"),
    ("(hive)$", "$1s"),
    ("([^aeiouy]|qu)y$", "$1ies"),
    ("(x|ch|ss|sh)$", "$1es"),
    ("(matr|vert|ind)ix|ex$", "$1ices"),
    ("([m|l])ouse$", "$1ice"),
    ("^(ox)$", "$1en"),
    ("(quiz)$", "$1zes"),
];

/// Rules used to turn a plural word into a singular one.
const SINGULAR_RULES: &[(&str, &str)] = &[
    ("s$", ""),
    ("(n)ews$", "$1ews"),
    ("([ti])a$", "$1um"),
    (
        "((a)naly|(b)a|(d)iagno|(p)arenthe|(p)rogno|(s)ynop|(t)he)ses$",
        "$1$2sis",
    ),
    ("(^analy)ses$", "$1sis"),
    ("([^f])ves$", "$1fe"),
    ("(hive)s$", "$1"),
    ("(tive)s$", "$1"),
    ("([lr])ves$", "$1f"),
    ("([^aeiouy]|qu)ies$", "$1y"),
    ("(s)eries$", "$1eries"),
    ("(m)ovies$", "$1ovie"),
    ("(x|ch|ss|sh)es$", "$1"),
    ("([m|l])ice$", "$1ouse"),
    ("(bus)es$", "$1"),
    ("(o)es$", "$1"),
    ("(shoe)s$", "$1"),
    ("(cris|ax|test)es$", "$1is"),
    ("(octop|vir)i$", "$1us"),
    ("(alias|status)es$", "$1"),
    ("^(ox)en$", "$1"),
    ("(vert|ind)ices$", "$1ex"),
    ("(matr)ices$", "$1ix"),
    ("(quiz)zes$", "$1"),
];

/// Words that are their own plural and their own singular.
///
/// Membership is an exact, case-sensitive string comparison, which is why
/// `sheep` is left alone but `Sheep` pluralises to `Sheeps` and `Jeans`
/// singularises to `Jean`.
const UNCOUNTABLES: &[&str] = &[
    "equipment",
    "information",
    "rice",
    "money",
    "species",
    "series",
    "fish",
    "sheep",
    "jeans",
    "police",
];

static PLURAL: OnceLock<Vec<Rule>> = OnceLock::new();
static SINGULAR: OnceLock<Vec<Rule>> = OnceLock::new();

/// Compiles a declaration-ordered table into `std::map` order.
///
/// Sorting by pattern reproduces the map's key ordering; the de-duplication step
/// reproduces `std::map`'s initializer-list construction, where the first
/// insertion of a key wins. `std::string`'s comparison and Rust's `str` ordering
/// are both unsigned byte-wise lexicographic, and every pattern here is ASCII,
/// so the two orderings agree exactly.
fn compile(table: &[(&'static str, &'static str)]) -> Vec<Rule> {
    let mut ordered: Vec<(&'static str, &'static str)> = table.to_vec();
    ordered.sort_by_key(|(pattern, _)| *pattern);
    ordered.dedup_by_key(|(pattern, _)| *pattern);

    ordered
        .into_iter()
        .map(|(pattern, replacement)| Rule {
            pattern,
            replacement,
            regex: Regex::new(pattern),
        })
        .collect()
}

/// The plural rules, in `std::map` order.
pub fn plural_rules() -> &'static [Rule] {
    PLURAL.get_or_init(|| compile(PLURAL_RULES))
}

/// The singular rules, in `std::map` order.
pub fn singular_rules() -> &'static [Rule] {
    SINGULAR.get_or_init(|| compile(SINGULAR_RULES))
}

/// True when `word` is an uncountable noun.
pub fn is_uncountable(word: &[u8]) -> bool {
    UNCOUNTABLES
        .iter()
        .any(|uncountable| uncountable.as_bytes() == word)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn plural_catch_all_sorts_first() {
        assert_eq!(plural_rules()[0].pattern, "$");
    }

    #[test]
    fn singular_catch_all_sorts_last() {
        assert_eq!(singular_rules().last().unwrap().pattern, "s$");
    }

    #[test]
    fn singular_rules_are_in_map_order() {
        let order: Vec<&str> = singular_rules().iter().map(|r| r.pattern).collect();
        assert_eq!(
            order,
            vec![
                "((a)naly|(b)a|(d)iagno|(p)arenthe|(p)rogno|(s)ynop|(t)he)ses$",
                "([^aeiouy]|qu)ies$",
                "([^f])ves$",
                "([lr])ves$",
                "([m|l])ice$",
                "([ti])a$",
                "(^analy)ses$",
                "(alias|status)es$",
                "(bus)es$",
                "(cris|ax|test)es$",
                "(hive)s$",
                "(m)ovies$",
                "(matr)ices$",
                "(n)ews$",
                "(o)es$",
                "(octop|vir)i$",
                "(quiz)zes$",
                "(s)eries$",
                "(shoe)s$",
                "(tive)s$",
                "(vert|ind)ices$",
                "(x|ch|ss|sh)es$",
                "^(ox)en$",
                "s$",
            ]
        );
    }

    #[test]
    fn uncountable_lookup_is_case_sensitive() {
        assert!(is_uncountable(b"sheep"));
        assert!(!is_uncountable(b"Sheep"));
        assert!(!is_uncountable(b"news"));
        assert!(!is_uncountable(b"deer"));
    }
}

