//! The ten `inflection::Inflector` entry points exercised by `test12`.
//!
//! Each one comes in two flavours: a `&[u8] -> Vec<u8>` form, which is what the
//! binary uses so that arbitrary argv bytes survive the round trip untouched, and
//! a `&str -> String` convenience wrapper for library callers.

use super::ascii;
use super::rules;

/// Namespace for the inflection functions, mirroring the C++ class of the same
/// name.
pub struct Inflector;

impl Inflector {
    /// Compiles the rule tables.
    ///
    /// The C++ original requires this before any other call; here the tables are
    /// behind a `OnceLock`, so it is only an eager warm-up and calling it is
    /// optional and idempotent.
    pub fn initialize() {
        rules::plural_rules();
        rules::singular_rules();
    }

    // ---------------------------------------------------------------- number

    /// Pluralises a word.
    ///
    /// Uncountable nouns are returned as they are; everything else picks up an
    /// `s`. It really is that blunt — see `rules.rs` for why the specific plural
    /// rules never get a look in.
    pub fn pluralize_bytes(word: &[u8]) -> Vec<u8> {
        if word.is_empty() || rules::is_uncountable(word) {
            return word.to_vec();
        }
        apply_first_matching(word, rules::plural_rules())
    }

    /// Singularises a word.
    ///
    /// Uncountable nouns are returned as they are; otherwise the first matching
    /// rule in map order wins, and words no rule recognises just lose a trailing
    /// `s`.
    pub fn singularize_bytes(word: &[u8]) -> Vec<u8> {
        if word.is_empty() || rules::is_uncountable(word) {
            return word.to_vec();
        }
        apply_first_matching(word, rules::singular_rules())
    }

    // ------------------------------------------------------------ word shape

    /// `hello_world` -> `helloWorld`.
    ///
    /// Underscores are dropped and the byte that follows each one is uppercased.
    /// The leading byte is left exactly as it was found, so `XMLParser` survives
    /// intact and `cat` stays lowercase.
    pub fn camelize_bytes(word: &[u8]) -> Vec<u8> {
        let mut out = Vec::with_capacity(word.len());
        let mut capitalize_next = false;
        for &byte in word {
            if byte == b'_' {
                capitalize_next = true;
            } else {
                out.push(if capitalize_next {
                    ascii::to_upper(byte)
                } else {
                    byte
                });
                capitalize_next = false;
            }
        }
        out
    }

    /// `HelloWorld` -> `hello_world`.
    ///
    /// Every uppercase byte other than the first is prefixed with an underscore,
    /// then lowercased. There is no acronym handling, so `XMLParser` comes out as
    /// `x_m_l_parser`, and an underscore already in the input is kept as-is,
    /// which is how `Hello_World` ends up as `hello__world`.
    pub fn underscore_bytes(word: &[u8]) -> Vec<u8> {
        let mut out = Vec::with_capacity(word.len() + word.len() / 4);
        for (index, &byte) in word.iter().enumerate() {
            if ascii::is_upper(byte) {
                if index > 0 {
                    out.push(b'_');
                }
                out.push(ascii::to_lower(byte));
            } else {
                out.push(byte);
            }
        }
        out
    }

    /// `user_accounts` -> `UserAccount`: singularise, camelize, capitalise.
    pub fn classify_bytes(word: &[u8]) -> Vec<u8> {
        let singular = Self::singularize_bytes(word);
        ascii::capitalize_first(Self::camelize_bytes(&singular))
    }

    /// `UserAccount` -> `user_accounts`: underscore, then pluralise.
    ///
    /// The order is worth spelling out because it is observable: `Sheep`
    /// underscores to `sheep` first, which *is* an uncountable, so the result is
    /// `sheep` and not `sheeps`.
    pub fn tableize_bytes(word: &[u8]) -> Vec<u8> {
        Self::pluralize_bytes(&Self::underscore_bytes(word))
    }

    /// `employee_id` -> `Employee id`.
    ///
    /// Underscores become spaces and the first byte is uppercased. Nothing else
    /// is touched: no trailing `_id` is stripped and the rest of the word keeps
    /// its original case, so `Hello_World` humanises to `Hello World`.
    pub fn humanize_bytes(word: &[u8]) -> Vec<u8> {
        ascii::capitalize_first(ascii::replace_byte(word, b'_', b' '))
    }

    /// `employee_id` -> `employee-id`. Case is left alone.
    pub fn dasherize_bytes(word: &[u8]) -> Vec<u8> {
        ascii::replace_byte(word, b'_', b'-')
    }

    // ----------------------------------------------------------------- case

    /// Uppercases the ASCII letters in a word.
    pub fn upcase_bytes(word: &[u8]) -> Vec<u8> {
        ascii::upcase(word)
    }

    /// Lowercases the ASCII letters in a word.
    pub fn downcase_bytes(word: &[u8]) -> Vec<u8> {
        ascii::downcase(word)
    }
}

/// Walks `table` in order and applies the first rule that matches.
fn apply_first_matching(word: &[u8], table: &[rules::Rule]) -> Vec<u8> {
    for rule in table {
        if rule.matches(word) {
            return rule.apply(word);
        }
    }
    word.to_vec()
}

/// Generates the `&str -> String` wrappers around the byte functions.
macro_rules! string_api {
    ($($name:ident => $bytes:ident, $doc:literal;)*) => {
        impl Inflector {
            $(
                #[doc = $doc]
                pub fn $name(word: &str) -> String {
                    // The transformations only ever move ASCII bytes around, so a
                    // UTF-8 input yields UTF-8 output; the lossy conversion is
                    // just belt and braces.
                    String::from_utf8_lossy(&Self::$bytes(word.as_bytes())).into_owned()
                }
            )*
        }
    };
}

string_api! {
    pluralize   => pluralize_bytes,   "Pluralises a word. See [`Inflector::pluralize_bytes`].";
    singularize => singularize_bytes, "Singularises a word. See [`Inflector::singularize_bytes`].";
    camelize    => camelize_bytes,    "`hello_world` -> `helloWorld`. See [`Inflector::camelize_bytes`].";
    underscore  => underscore_bytes,  "`HelloWorld` -> `hello_world`. See [`Inflector::underscore_bytes`].";
    classify    => classify_bytes,    "`user_accounts` -> `UserAccount`. See [`Inflector::classify_bytes`].";
    tableize    => tableize_bytes,    "`UserAccount` -> `user_accounts`. See [`Inflector::tableize_bytes`].";
    humanize    => humanize_bytes,    "`employee_id` -> `Employee id`. See [`Inflector::humanize_bytes`].";
    dasherize   => dasherize_bytes,   "`employee_id` -> `employee-id`. See [`Inflector::dasherize_bytes`].";
    upcase      => upcase_bytes,      "Uppercases the ASCII letters in a word.";
    downcase    => downcase_bytes,    "Lowercases the ASCII letters in a word.";
}

#[cfg(test)]
mod tests {
    use super::Inflector as I;

    #[test]
    fn documented_example_one() {
        assert_eq!(I::pluralize("cat"), "cats");
        assert_eq!(I::singularize("cat"), "cat");
        assert_eq!(I::camelize("hello_world"), "helloWorld");
        assert_eq!(I::underscore("hello_world"), "hello_world");
        assert_eq!(I::classify("user_account"), "UserAccount");
        assert_eq!(I::tableize("user_account"), "user_accounts");
        assert_eq!(I::humanize("employee_id"), "Employee id");
        assert_eq!(I::dasherize("employee_id"), "employee-id");
        assert_eq!(I::upcase("employee_id"), "EMPLOYEE_ID");
        assert_eq!(I::downcase("employee_id"), "employee_id");
    }

    #[test]
    fn documented_examples_two_to_five() {
        assert_eq!(I::pluralize("dog"), "dogs");
        assert_eq!(I::camelize("my_class_name"), "myClassName");
        assert_eq!(I::classify("order_item"), "OrderItem");
        assert_eq!(I::tableize("order_item"), "order_items");
        assert_eq!(I::humanize("created_at"), "Created at");

        assert_eq!(I::pluralize("box"), "boxs");
        assert_eq!(I::camelize("XMLParser"), "XMLParser");
        assert_eq!(I::underscore("XMLParser"), "x_m_l_parser");
        assert_eq!(I::tableize("person"), "persons");

        assert_eq!(I::pluralize("child"), "childs");
        assert_eq!(I::underscore("HTTPRequest"), "h_t_t_p_request");
        assert_eq!(I::classify("mouse"), "Mouse");
        assert_eq!(I::tableize("mouse"), "mouses");

        assert_eq!(I::camelize("api_client"), "apiClient");
        assert_eq!(I::classify("tooth"), "Tooth");
        assert_eq!(I::tableize("tooth"), "tooths");
        assert_eq!(I::humanize("last_name"), "Last name");
    }

    #[test]
    fn pluralize_is_a_bare_s() {
        for (word, plural) in [
            ("bus", "buss"),
            ("city", "citys"),
            ("quiz", "quizs"),
            ("ox", "oxs"),
            ("knife", "knifes"),
            ("analysis", "analysiss"),
            ("matrix", "matrixs"),
            ("news", "newss"),
            ("deer", "deers"),
        ] {
            assert_eq!(I::pluralize(word), plural, "pluralize({word})");
        }
    }

    #[test]
    fn uncountables_survive_both_directions() {
        for word in ["equipment", "information", "rice", "money", "species", "series", "fish", "sheep", "jeans", "police"] {
            assert_eq!(I::pluralize(word), word);
            assert_eq!(I::singularize(word), word);
        }
        // Case-sensitive membership.
        assert_eq!(I::pluralize("Sheep"), "Sheeps");
        assert_eq!(I::singularize("Jeans"), "Jean");
    }

    #[test]
    fn singularize_follows_map_order() {
        for (word, singular) in [
            ("boxes", "box"),
            ("cities", "city"),
            ("buses", "bus"),
            ("mice", "mouse"),
            ("oxen", "ox"),
            ("vertices", "vertex"),
            ("matrices", "matrix"),
            ("quizzes", "quiz"),
            ("aliases", "alias"),
            ("crises", "crisis"),
            ("octopi", "octopus"),
            ("media", "medium"),
            ("news", "news"),
            // Map order beats the Rails ordering here:
            ("shoes", "sho"),
            ("movies", "movy"),
            ("hives", "hife"),
            ("wolves", "wolfe"),
            ("leaves", "leafe"),
            ("ties", "ty"),
            // `$1$2sis` quirk:
            ("analyses", "analyasis"),
            ("bases", "basis"),
            ("theses", "thesis"),
            ("databases", "databasis"),
            ("parentheses", "parenthesis"),
            // Fall-through to the catch-all:
            ("class", "clas"),
            ("analysis", "analysi"),
            ("bus", "bu"),
            ("s", ""),
        ] {
            assert_eq!(I::singularize(word), singular, "singularize({word})");
        }
    }

    #[test]
    fn singularize_is_case_sensitive() {
        for word in ["BOXES", "CITIES", "ANALYSES", "MICE", "OXEN", "JEANS"] {
            assert_eq!(I::singularize(word), word, "singularize({word})");
        }
        assert_eq!(I::singularize("Boxes"), "Box");
        assert_eq!(I::singularize("Buses"), "Buse");
        assert_eq!(I::singularize("Analyses"), "Analyse");
    }

    #[test]
    fn shape_helpers_handle_separator_runs() {
        assert_eq!(I::camelize("a__b"), "aB");
        assert_eq!(I::camelize("_leading"), "Leading");
        assert_eq!(I::camelize("trailing_"), "trailing");
        assert_eq!(I::camelize("__"), "");
        assert_eq!(I::underscore("Hello_World"), "hello__world");
        assert_eq!(I::humanize("a__b"), "A  b");
        assert_eq!(I::humanize("_leading"), " leading");
        assert_eq!(I::dasherize("a__b"), "a--b");
    }

    #[test]
    fn classify_singularizes_before_camelizing() {
        // camelize-first would yield "Mouse"; singularize-first yields "Mice".
        assert_eq!(I::classify("mice_"), "Mice");
        assert_eq!(I::classify("_ies"), "Y");
        assert_eq!(I::classify("s"), "");
    }

    #[test]
    fn tableize_underscores_before_pluralizing() {
        // pluralize-first would yield "sheeps".
        assert_eq!(I::tableize("Sheep"), "sheep");
        assert_eq!(I::tableize("SHEEP"), "s_h_e_e_ps");
        assert_eq!(I::tableize("ABC"), "a_b_cs");
    }

    #[test]
    fn empty_input_stays_empty() {
        assert_eq!(I::pluralize(""), "");
        assert_eq!(I::singularize(""), "");
        assert_eq!(I::camelize(""), "");
        assert_eq!(I::underscore(""), "");
        assert_eq!(I::classify(""), "");
        assert_eq!(I::tableize(""), "");
        assert_eq!(I::humanize(""), "");
        assert_eq!(I::dasherize(""), "");
        assert_eq!(I::upcase(""), "");
        assert_eq!(I::downcase(""), "");
    }

    #[test]
    fn multibyte_input_is_passed_through() {
        assert_eq!(I::upcase("ünïcode"), "üNïCODE");
        assert_eq!(I::classify("a_ü_b"), "AüB");
        assert_eq!(I::humanize("a_ü_b"), "A ü b");
    }
}

