    }
}

/// Walks `table` in order and applies the first rule that matches.
fn apply_first_matching(word: &[u8], table: &[rules::Rule]) -> Vec<u8> {
    for rule in table {
        if rule.matches(word) {
            return rule.apply(word);
        }
    }
