    singularize => singularize_bytes, "Singularises a word. See [`Inflector::singularize_bytes`].";
    camelize    => camelize_bytes,    "`hello_world` -> `helloWorld`. See [`Inflector::camelize_bytes`].";
    underscore  => underscore_bytes,  "`HelloWorld` -> `hello_world`. See [`Inflector::underscore_bytes`].";
    classify    => classify_bytes,    "`user_accounts` -> `UserAccount`. See [`Inflector::classify_bytes`].";
    tableize    => tableize_bytes,    "`UserAccount` -> `user_accounts`. See [`Inflector::tableize_bytes`].";
    humanize    => humanize_bytes,    "`employee_id` -> `Employee id`. See [`Inflector::humanize_bytes`].";
    dasherize   => dasherize_bytes,   "`employee_id` -> `employee-id`. See [`Inflector::dasherize_bytes`].";
    upcase      => upcase_bytes,      "Uppercases the ASCII letters in a word.";
    downcase    => downcase_bytes,    "Lowercases the ASCII letters in a word.";
